11: const ScrambleTag = ({ text }: { text: string }) => {
12:   const textRef = useRef<HTMLSpanElement>(null);
13:   const originalText = useRef(text);
14:   const isAnimating = useRef(false);
15: 
16:   const handleHover = () => {
17:     if (isAnimating.current || !textRef.current) return;
18:     isAnimating.current = true;
19:     let step = 0;
20:     const steps = 15;
21:     const chars = '!<>-_\\/[]{}—=+*^?#________';
22:     
23:     const interval = setInterval(() => {
24:       let scrambled = '';
25:       for (let i = 0; i < originalText.current.length; i++) {
26:         if (originalText.current[i] === ' ') {
27:           scrambled += ' ';
28:         } else {
29:           scrambled += chars[Math.floor(Math.random() * chars.length)];
30:         }
31:       }
32:       if (textRef.current) textRef.current.innerText = scrambled;
33:       step++;
34:       if (step > steps) { 
35:         clearInterval(interval); 
36:         if(textRef.current) textRef.current.innerText = originalText.current; 
37:         isAnimating.current = false; 
38:       }
39:     }, 40);
40:   };
41: 
42:   return (
43:     <div 
44:       className="system-tag relative z-20 mb-6 inline-flex items-center gap-2 font-mono text-sm tracking-widest uppercase cursor-default group"
45:       onMouseEnter={handleHover}
46:     >
47:       <span className="text-[#2EFF00] font-bold">&gt;_</span> 
48:       <span className="text-[#2EFF00] text-lg leading-none">●</span> 
49:       <span className="text-[#2EFF00] group-hover:opacity-80 transition-opacity" ref={textRef}>{text}</span>
50:     </div>
51:   );
52: };
